        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
        overflow: hidden;
      }

      .card-header {
        padding: 24px 24px 0;
      }

      .form {
        padding: 24px;
      }

      .grid {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        color: #f8fafc;
      }

      input {
        width: 100%;
        border: 1px solid var(--field-border);
        border-radius: 14px;
        background: var(--field);
        color: var(--text);
        padding: 14px 16px;
        font-size: 1rem;
        outline: none;
        transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
      }

      input::placeholder {
        color: #64748b;
      }

      input:focus {
        border-color: #8b5cf6;
        box-shadow: 0 0 0 4px var(--focus);
      }

      input[aria-invalid="true"] {
        border-color: rgba(251, 113, 133, 0.95);
        box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
      }

      .helper {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .error {
        min-height: 1.15em;
        color: var(--danger);
        font-size: 0.92rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 6px;
      }

      .button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        background: linear-gradient(135deg, #8b5cf6, #22c55e);
        color: white;
        font-weight: 700;
        font-size: 1rem;
        cursor: pointer;
        box-shadow: 0 16px 30px rgba(124, 58, 237, 0.3);
        transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
        box-shadow: 0 20px 34px rgba(124, 58, 237, 0.36);
