        --muted: #94a3b8;
        --accent: #7c3aed;
        --accent-2: #22c55e;
        --danger: #fb7185;
        --field: #0f172a;
        --field-border: #334155;
        --focus: rgba(124, 58, 237, 0.35);
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        min-height: 100vh;
        background:
          radial-gradient(circle at top, rgba(124, 58, 237, 0.22), transparent 30%),
          radial-gradient(circle at bottom right, rgba(34, 197, 94, 0.12), transparent 35%),
          linear-gradient(180deg, #050816 0%, #0b1020 100%);
        color: var(--text);
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .page {
        width: min(100%, 760px);
      }

      .hero {
        margin-bottom: 20px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        color: var(--accent-2);
        text-transform: uppercase;
        letter-spacing: 0.14em;
        font-size: 0.78rem;
        font-weight: 700;
      }

      .hero h1 {
        margin: 10px 0 8px;
        font-size: clamp(2rem, 4vw, 3.2rem);
        line-height: 1.05;
      }

      .hero p {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.02rem;
      }

      .card {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
        overflow: hidden;
      }

      .card-header {
        padding: 24px 24px 0;
      }

      .form {
        padding: 24px;
      }

      .grid {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        color: #f8fafc;
      }

      input {
        width: 100%;
        border: 1px solid var(--field-border);
        border-radius: 14px;
        background: var(--field);
        color: var(--text);
        padding: 14px 16px;
        font-size: 1rem;
        outline: none;
        transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
      }

      input::placeholder {
        color: #64748b;
      }

      input:focus {
        border-color: #8b5cf6;
        box-shadow: 0 0 0 4px var(--focus);
      }

      input[aria-invalid="true"] {
        border-color: rgba(251, 113, 133, 0.95);
        box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
      }

      .helper {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .error {
        min-height: 1.15em;
        color: var(--danger);
        font-size: 0.92rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 6px;
      }

      .button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        background: linear-gradient(135deg, #8b5cf6, #22c55e);
        color: white;
        font-weight: 700;
        font-size: 1rem;
        cursor: pointer;
        box-shadow: 0 16px 30px rgba(124, 58, 237, 0.3);
        transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
        box-shadow: 0 20px 34px rgba(124, 58, 237, 0.36);
        filter: brightness(1.02);
      }

      .button:active {
        transform: translateY(0);
      }

      .status {
        margin-top: 18px;
        padding: 14px 16px;
        border-radius: 14px;
        background: rgba(34, 197, 94, 0.12);
        border: 1px solid rgba(34, 197, 94, 0.22);
        color: #bbf7d0;
        display: none;
      }

      .status.show {
        display: block;
      }

      @media (max-width: 640px) {
        body {
          padding: 16px;
        }

        .card-header,
        .form {
          padding-left: 18px;
          padding-right: 18px;
        }

        .actions {
          justify-content: stretch;
        }

        .button {
          width: 100%;
        }
      }
    </style>
  </head>
