    <script>
      const root = document.getElementById("root");
      const requiredMessage = (label) => `${label} is required.`;
      const emailMessage = "Enter a valid email address.";
      const phoneMessage = "Enter a valid phone number or leave this field blank.";

      function createEl(tag, options = {}, ...children) {
        const el = document.createElement(tag);
        if (options.className) el.className = options.className;
        if (options.textContent !== undefined) el.textContent = options.textContent;
        if (options.htmlFor) el.htmlFor = options.htmlFor;
        if (options.id) el.id = options.id;
        if (options.type) el.type = options.type;
        if (options.name) el.name = options.name;
        if (options.placeholder) el.placeholder = options.placeholder;
        if (options.autoComplete) el.autocomplete = options.autoComplete;
        if (options.inputMode) el.inputMode = options.inputMode;
        if (options.required) el.required = true;
        if (options.role) el.setAttribute("role", options.role);
        if (options.ariaLive) el.setAttribute("aria-live", options.ariaLive);
        if (options.ariaInvalid !== undefined) el.setAttribute("aria-invalid", String(options.ariaInvalid));
        if (options.describedBy) el.setAttribute("aria-describedby", options.describedBy);
        if (options.value !== undefined) el.value = options.value;
        if (options.style) Object.assign(el.style, options.style);
        if (options.onClick) el.addEventListener("click", options.onClick);
        if (options.onInput) el.addEventListener("input", options.onInput);
        if (options.onBlur) el.addEventListener("blur", options.onBlur);
        if (options.onSubmit) el.addEventListener("submit", options.onSubmit);
        children.flat().forEach((child) => {
          if (child === null || child === undefined) return;
          el.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
        });
        return el;
      }

      function SupportContactForm() {
        const state = {
          values: { fullName: "", email: "", phone: "" },
          touched: { fullName: false, email: false, phone: false },
          submitted: false
        };

        const form = createEl("form", { className: "form" });
        const status = createEl("div", { className: "status", role: "status", ariaLive: "polite", textContent: "Thanks — your message is ready to send." });

        const fields = {
          fullName: {},
          email: {},
          phone: {}
        };

        function getErrors() {
          const next = {};
          const fullName = state.values.fullName.trim();
          const email = state.values.email.trim();
          const phone = state.values.phone.trim();

          if (!fullName) next.fullName = requiredMessage("Full name");
          if (!email) {
            next.email = requiredMessage("Email address");
          } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            next.email = emailMessage;
          }

          if (phone && !/^\+?[0-9()\-\s]{7,}$/.test(phone)) {
            next.phone = phoneMessage;
          }

          return next;
        }

        function updateField(name) {
          const errors = getErrors();
          const showError = state.touched[name] || state.submitted;
          const message = showError ? errors[name] || "" : "";
          fields[name].input.value = state.values[name];
          fields[name].input.setAttribute("aria-invalid", String(Boolean(message)));
          fields[name].error.textContent = message || "\u00A0";
        }

        function syncForm() {
          ["fullName", "email", "phone"].forEach(updateField);
          status.classList.toggle("show", state.submitted && Object.keys(getErrors()).length === 0);
        }

        function setValue(name, value) {
          state.values[name] = value;
          state.submitted = false;
          syncForm();
        }

        function setTouched(name) {
          state.touched[name] = true;
          syncForm();
        }

        function buildField({ id, label, type = "text", required = false, helperText, placeholder, autoComplete, inputMode }) {
