          form
        );

        const page = createEl(
          "main",
          { className: "page" },
          createEl(
            "section",
            { className: "hero", "aria-label": "Support contact form introduction" },
            createEl("div", { className: "eyebrow", textContent: "Support" }),
            createEl("h1", { textContent: "Contact our support team" }),
            createEl("p", { textContent: "Send us your details and we will get back to you with the right help as soon as possible." })
          ),
          card
        );

        root.appendChild(page);
        syncForm();
      }

      SupportContactForm();
    </script>
